const { execFile } = require('child_process');

/**
 * Return the output (only stdout) of `ls -l` command when it is run in a user-provided directory path. If any error occurs during the command execution (e.g. directory not found, permission error), return an empty string.
 *
 * @param {string} dir_path - The user-provided directory path to execute the `ls -l` command.
 * @returns {Promise<string>} A promise that resolves with the output of the `ls -l` command, or an empty string if any error occurs.
 */
function get_ls_result(dir_path) {
    return new Promise((resolve) => {
        // Using `execFile` is preferred over `exec` for security reasons when executing
        // a specific command with user-provided arguments. It directly executes the command
        // without involving a shell, thus preventing shell injection vulnerabilities.
        // 'ls' is the command, and ['-l', dir_path] are the arguments passed to it.
        execFile('ls', ['-l', dir_path], (error, stdout, stderr) => {
            if (error) {
                // If an error occurs during the execution of the 'ls' command (e.g.,
                // the directory does not exist, permission is denied, or 'ls' itself
                // is not found, or it exits with a non-zero status code),
                // the promise resolves with an empty string as per the docstring.
                resolve('');
            } else {
                // If the command executes successfully, the promise resolves with
                // the standard output (stdout) of the 'ls -l' command.
                resolve(stdout);
            }
        });
    });
}
